import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { deleteRequest, getRequests } from '../services/requestService';
import { useAuth } from '../context/AuthContext';
import { toast } from 'react-toastify';
import { FiFileText, FiCalendar, FiUser, FiCheckCircle, FiClock, FiXCircle, FiAlertCircle, FiTrash2, FiEye, FiFilter, FiSearch, FiChevronUp, FiChevronDown, FiChevronLeft, FiChevronRight } from 'react-icons/fi';

const RequestList = () => {
  const { user } = useAuth();
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [deletingId, setDeletingId] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [viewMode, setViewMode] = useState('cards'); // 'cards' or 'table'
  const [darkMode, setDarkMode] = useState(() => {
    try { return localStorage.getItem('darkMode') === 'true'; } catch (e) { return false; }
  });

  useEffect(() => {
    try { localStorage.setItem('darkMode', darkMode ? 'true' : 'false'); } catch (e) {}
  }, [darkMode]);

  useEffect(() => {
    loadRequests();
  }, []);

  const getStatusIcon = (status) => {
    switch (status) {
      case 'approved': return <FiCheckCircle className="w-5 h-5" />;
      case 'pending': return <FiClock className="w-5 h-5" />;
      case 'rejected': return <FiXCircle className="w-5 h-5" />;
      case 'in_progress': return <FiAlertCircle className="w-5 h-5" />;
      default: return <FiFileText className="w-5 h-5" />;
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'approved': return 'bg-green-100 text-green-800 border-green-200';
      case 'pending': return 'bg-blue-100 text-blue-800 border-blue-200';
      case 'rejected': return 'bg-red-100 text-red-800 border-red-200';
      case 'in_progress': return 'bg-amber-100 text-amber-800 border-amber-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const getStatusPercentage = (count) => {
    if (!stats.total) return 0;
    return Math.round((count / stats.total) * 100);
  };

  const getStatusBarClass = (status) => {
    switch (status) {
      case 'approved': return 'bg-gradient-to-r from-emerald-500 to-lime-400';
      case 'pending': return 'bg-gradient-to-r from-sky-500 to-cyan-500';
      case 'rejected': return 'bg-gradient-to-r from-red-500 to-rose-500';
      case 'in_progress': return 'bg-gradient-to-r from-amber-500 to-yellow-400';
      case 'draft': return 'bg-gradient-to-r from-slate-500 to-slate-400';
      default: return 'bg-gradient-to-r from-slate-500 to-slate-400';
    }
  };

  const statusLabel = (status) => {
    switch (status) {
      case 'approved': return 'Approuvé';
      case 'pending': return 'En attente';
      case 'rejected': return 'Rejeté';
      case 'in_progress': return 'En cours';
      case 'draft': return 'Brouillon';
      default: return status;
    }
  };

  const [sortBy, setSortBy] = useState('createdAt');
  const [sortDir, setSortDir] = useState('desc');
  const [currentPage, setCurrentPage] = useState(1);
  const pageSize = 8;

  const filteredRequests = requests.filter((req) => {
    const matchesSearch = req.reference.toLowerCase().includes(searchTerm.toLowerCase()) ||
                          req.workflowType.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filterStatus === 'all' || req.status === filterStatus;
    return matchesSearch && matchesFilter;
  });

  const getSortedRequests = (items) => {
    if (!sortBy) return items;
    return [...items].sort((a, b) => {
      const aVal = a[sortBy] || '';
      const bVal = b[sortBy] || '';
      if (sortBy === 'createdAt') {
        return sortDir === 'asc' ? new Date(aVal) - new Date(bVal) : new Date(bVal) - new Date(aVal);
      }
      const A = String(aVal).toLowerCase();
      const B = String(bVal).toLowerCase();
      if (A < B) return sortDir === 'asc' ? -1 : 1;
      if (A > B) return sortDir === 'asc' ? 1 : -1;
      return 0;
    });
  };

  const sortedRequests = getSortedRequests(filteredRequests);
  const totalPages = Math.max(1, Math.ceil(sortedRequests.length / pageSize));
  const paginatedRequests = sortedRequests.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  const handleSort = (column) => {
    if (sortBy === column) {
      setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortBy(column);
      setSortDir('asc');
    }
    setCurrentPage(1);
  };

  const changePage = (delta) => {
    setCurrentPage((p) => {
      const next = p + delta;
      if (next < 1) return 1;
      if (next > totalPages) return totalPages;
      return next;
    });
  };

  const getStatusStats = () => ({
    total: requests.length,
    approved: requests.filter((r) => r.status === 'approved').length,
    pending: requests.filter((r) => r.status === 'pending').length,
    rejected: requests.filter((r) => r.status === 'rejected').length,
    in_progress: requests.filter((r) => r.status === 'in_progress').length,
    draft: requests.filter((r) => r.status === 'draft').length,
  });

  const stats = getStatusStats();

  const loadRequests = async () => {
    try {
      const data = await getRequests();
      const mine = data.filter((req) => Number(req.createdBy) === Number(user?.id));
      setRequests(mine);
    } catch (error) {
      toast.error('Erreur lors du chargement des demandes');
      setRequests([]);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id) => {
    const confirmed = window.confirm('Voulez-vous vraiment supprimer cette demande ?');
    if (!confirmed) return;

    try {
      setDeletingId(id);
      await deleteRequest(id);
      setRequests((prev) => prev.filter((req) => req.id !== id));
      toast.success('Demande supprimée avec succès');
    } catch (error) {
      toast.error(error?.response?.data?.message || 'Erreur lors de la suppression');
    } finally {
      setDeletingId(null);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-300 via-slate-400 to-slate-500">
      <div className="container mx-auto px-4 py-10">
        <div className="rounded-[32px] border border-white/80 bg-slate-300/95 shadow-[0_30px_80px_rgba(15,23,42,0.12)] backdrop-blur-xl overflow-hidden">
          <div className="bg-gradient-to-r from-slate-950 via-blue-800 to-indigo-950 px-6 py-10 sm:px-10 sm:py-12">
            <div className="flex flex-col gap-8 lg:flex-row lg:items-end lg:justify-between">
              <div className="max-w-3xl">
                <span className="inline-flex rounded-full bg-white/10 px-4 py-1 text-xs uppercase tracking-[0.35em] text-slate-200 ring-1 ring-white/20">
                  Gestion des demandes
                </span>
                <h1 className="mt-5 text-4xl font-semibold tracking-tight text-white sm:text-5xl">
                  Mes demandes
                </h1>
                <p className="mt-4 max-w-2xl text-base leading-8 text-slate-200/85 sm:text-lg">
                  Suivez et gérez vos demandes avec un tableau clair, des filtres rapides et un aperçu instantané de l’état de vos workflows.
                </p>
              </div>
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="flex items-center gap-3">
                  <Link
                    to="/requests/new"
                    className="inline-flex items-center justify-center gap-2 rounded-full bg-slate-100 px-6 py-3 text-sm font-semibold text-slate-950 shadow-lg transition hover:bg-slate-200"
                  >
                    <FiFileText className="w-4 h-4" />
                    Nouvelle demande
                  </Link>
                </div>
                <div className="rounded-[28px] border border-white/20 bg-white/10 p-6 text-center text-white shadow-[0_25px_60px_rgba(15,23,42,0.18)] backdrop-blur-xl">
                  <p className="text-xs uppercase tracking-[0.3em] text-slate-200">Demandes après filtre</p>
                  <p className="mt-4 text-4xl font-semibold text-white">{filteredRequests.length}</p>
                  <p className="mt-2 text-sm text-slate-200/75">Affichage en temps réel</p>
                </div>
              </div>
            </div>
          </div>

          <div className="px-4 py-8 sm:px-8 sm:py-10">
            {!loading && requests.length > 0 && (
              <div className="grid grid-cols-1 gap-4 lg:grid-cols-[1fr_1.8fr] mb-8">
                <div className="rounded-[32px] border border-slate-200 bg-slate-200 p-6 shadow-sm">
                  <p className="text-sm uppercase tracking-[0.25em] text-slate-500">Vue d’ensemble</p>
                  <h2 className="mt-3 text-3xl font-semibold text-slate-900">Performance globale</h2>
                  <p className="mt-2 text-sm text-slate-500">Votre tableau de bord de demandes résume les statuts clés et l’activité récente.</p>

                  <div className="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-3">
                    <div className="rounded-3xl border border-slate-200 bg-slate-100 p-5 shadow-sm">
                      <p className="text-xs uppercase tracking-[0.25em] text-slate-400">Total</p>
                      <p className="mt-4 text-4xl font-semibold text-slate-900">{stats.total}</p>
                      <div className="mt-4 h-2 rounded-full bg-slate-200">
                        <div className="h-full rounded-full bg-gradient-to-r from-slate-900 to-slate-500" style={{ width: '100%' }} />
                      </div>
                    </div>
                    <div className="rounded-3xl border border-slate-200 bg-slate-50 p-5 shadow-sm">
                      <p className="text-xs uppercase tracking-[0.25em] text-sky-500">En attente</p>
                      <p className="mt-4 text-4xl font-semibold text-sky-700">{stats.pending}</p>
                      <div className="mt-4 h-2 rounded-full bg-slate-200">
                        <div className="h-full rounded-full bg-gradient-to-r from-sky-500 to-cyan-500" style={{ width: `${getStatusPercentage(stats.pending)}%` }} />
                      </div>
                    </div>
                    <div className="rounded-3xl border border-slate-200 bg-slate-50 p-5 shadow-sm">
                      <p className="text-xs uppercase tracking-[0.25em] text-emerald-500">Approuvé</p>
                      <p className="mt-4 text-4xl font-semibold text-emerald-700">{stats.approved}</p>
                      <div className="mt-4 h-2 rounded-full bg-slate-200">
                        <div className="h-full rounded-full bg-gradient-to-r from-emerald-500 to-lime-500" style={{ width: `${getStatusPercentage(stats.approved)}%` }} />
                      </div>
                    </div>
                    <div className="rounded-3xl border border-slate-200 bg-slate-50 p-5 shadow-sm">
                      <p className="text-xs uppercase tracking-[0.25em] text-amber-500">En cours</p>
                      <p className="mt-4 text-4xl font-semibold text-amber-700">{stats.in_progress}</p>
                      <div className="mt-4 h-2 rounded-full bg-slate-200">
                        <div className="h-full rounded-full bg-gradient-to-r from-amber-500 to-yellow-400" style={{ width: `${getStatusPercentage(stats.in_progress)}%` }} />
                      </div>
                    </div>
                    <div className="rounded-3xl border border-slate-200 bg-slate-50 p-5 shadow-sm">
                      <p className="text-xs uppercase tracking-[0.25em] text-red-500">Rejeté</p>
                      <p className="mt-4 text-4xl font-semibold text-red-700">{stats.rejected}</p>
                      <div className="mt-4 h-2 rounded-full bg-slate-200">
                        <div className="h-full rounded-full bg-gradient-to-r from-red-500 to-rose-500" style={{ width: `${getStatusPercentage(stats.rejected)}%` }} />
                      </div>
                    </div>
                    <div className="rounded-3xl border border-slate-200 bg-slate-50 p-5 shadow-sm">
                      <p className="text-xs uppercase tracking-[0.25em] text-slate-500">Brouillon</p>
                      <p className="mt-4 text-4xl font-semibold text-slate-900">{stats.draft}</p>
                      <div className="mt-4 h-2 rounded-full bg-slate-200">
                        <div className="h-full rounded-full bg-gradient-to-r from-slate-500 to-slate-400" style={{ width: `${getStatusPercentage(stats.draft)}%` }} />
                      </div>
                    </div>
                  </div>
                </div>
                <div className="rounded-[32px] border border-slate-200 bg-slate-50 p-6 shadow-sm">
                  <p className="text-sm uppercase tracking-[0.25em] text-slate-500">Statut en temps réel</p>
                  <div className="mt-6 space-y-4">
                    {['pending', 'approved', 'in_progress', 'rejected', 'draft'].map((status) => (
                      <div key={status} className="space-y-2">
                        <div className="flex items-center justify-between text-sm font-semibold text-slate-700">
                          <span>{statusLabel(status)}</span>
                          <span>{getStatusPercentage(stats[status])}%</span>
                        </div>
                        <div className="h-2 rounded-full bg-slate-200">
                          <div className={`h-full rounded-full ${getStatusBarClass(status)}`} style={{ width: `${getStatusPercentage(stats[status])}%` }} />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            )}

            <div className="grid gap-6 xl:grid-cols-[1.45fr_0.85fr] mb-6">
              <div className="rounded-[28px] border border-slate-200 bg-slate-200 p-6 shadow-sm">
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                  <div>
                    <h2 className="text-xl font-semibold text-slate-900">Recherche et filtre</h2>
                  </div>
                  <div className="inline-flex overflow-hidden rounded-full border border-slate-200 bg-slate-100 shadow-sm">
                    {['all', 'pending', 'approved', 'in_progress', 'rejected', 'draft'].map((status) => (
                      <button
                        key={status}
                        type="button"
                        onClick={() => setFilterStatus(status)}
                        className={`px-4 py-2 text-sm font-semibold transition ${filterStatus === status ? 'bg-slate-900 text-white' : 'text-slate-600 hover:bg-slate-100'}`}
                      >
                        {status === 'all' ? 'Tous' : status === 'pending' ? 'En attente' : status === 'approved' ? 'Approuvé' : status === 'in_progress' ? 'En cours' : status === 'rejected' ? 'Rejeté' : 'Brouillon'}
                      </button>
                    ))}
                  </div>
                </div>
                <div className="mt-6 relative">
                  <FiSearch className="pointer-events-none absolute left-4 top-1/2 -translate-y-1/2 text-slate-400 w-5 h-5" />
                  <input
                    type="text"
                    placeholder="Rechercher par référence ou type..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="w-full rounded-[24px] border border-slate-300 bg-slate-100 py-4 pl-12 pr-4 text-sm text-slate-900 shadow-sm outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-200"
                  />
                </div>
              </div>

              <div className="rounded-[28px] border border-slate-200 bg-slate-50 p-6 shadow-sm">
                <div className="flex items-center justify-between gap-4">
                  <div>
                    <h2 className="text-xl font-semibold text-slate-900">Mode d’affichage</h2>
                  </div>
                </div>
                <div className="mt-6 flex flex-wrap gap-3">
                  <button
                    type="button"
                    onClick={() => setViewMode('cards')}
                    className={`inline-flex items-center gap-2 rounded-full px-4 py-3 text-sm font-semibold transition ${viewMode === 'cards' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-700 ring-1 ring-slate-200 hover:bg-slate-100'}`}
                  >
                    <FiFileText className="w-4 h-4" />
                    Cartes
                  </button>
                  <button
                    type="button"
                    onClick={() => setViewMode('table')}
                    className={`inline-flex items-center gap-2 rounded-full px-4 py-3 text-sm font-semibold transition ${viewMode === 'table' ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-50 text-slate-700 ring-1 ring-slate-200 hover:bg-slate-100'}`}
                  >
                    <FiFilter className="w-4 h-4" />
                    Tableau
                  </button>
                </div>
                <div className="mt-6 rounded-3xl border border-slate-200 bg-slate-100 p-4 text-sm text-slate-600">
                  <p className="font-medium text-slate-900">Total</p>
                  <p className="mt-2">{stats.total} demandes</p>
                  <div className="mt-4 grid gap-3 sm:grid-cols-2">
                    <div className="rounded-2xl bg-slate-100 p-3 shadow-sm">
                      <p className="text-xs uppercase tracking-[0.25em] text-slate-400">Trouvées</p>
                      <p className="mt-2 text-lg font-semibold text-slate-900">{filteredRequests.length}</p>
                    </div>
                    <div className="rounded-2xl bg-slate-100 p-3 shadow-sm">
                      <p className="text-xs uppercase tracking-[0.25em] text-slate-400">Visibilité</p>
                      <p className="mt-2 text-lg font-semibold text-slate-900">{viewMode === 'cards' ? 'Cartes' : 'Tableau'}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {!loading && filteredRequests.length === 0 && (
                <div className="rounded-[28px] border border-slate-200 bg-slate-200 p-10 text-center shadow-sm">
                  <div className="mx-auto flex h-24 w-24 items-center justify-center rounded-full bg-slate-300 text-slate-600">
                  <FiFileText className="w-10 h-10" />
                </div>
                <h3 className="mt-6 text-2xl font-semibold text-slate-900">{requests.length === 0 ? 'Aucune demande trouvée' : 'Aucun résultat trouvé'}</h3>
                <p className="mt-2 text-sm text-slate-500">
                  {requests.length === 0 ? 'Vos demandes apparaîtront ici une fois créées' : 'Essayez de modifier vos filtres de recherche'}
                </p>
                {requests.length === 0 && (
                  <Link
                    to="/requests/new"
                    className="mt-6 inline-flex items-center justify-center gap-2 rounded-full bg-blue-600 px-6 py-3 text-sm font-semibold text-white transition hover:bg-blue-700"
                  >
                    <FiFileText className="w-4 h-4" />
                    Créer votre première demande
                  </Link>
                )}
              </div>
            )}

            {!loading && filteredRequests.length > 0 && (
              <div className="space-y-6">
                {viewMode === 'cards' ? (
                  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                    {filteredRequests.map((req) => {
                      const assignedToMe = req.assignedTo === user?.id || req.assignee?.id === user?.id;
                      return (
                        <div
                          key={req.id}
                          className="group rounded-[28px] border border-slate-200 bg-slate-100 p-6 shadow-[0_24px_60px_rgba(15,23,42,0.08)] transition hover:-translate-y-1 hover:shadow-[0_32px_90px_rgba(15,23,42,0.12)]"
                        >
                          <div className="flex items-start justify-between gap-4">
                            <div>
                              <span className="inline-flex rounded-full bg-gradient-to-r from-blue-600 to-indigo-600 px-3 py-1 text-xs font-semibold uppercase tracking-[0.18em] text-white shadow-sm">{req.reference}</span>
                              {assignedToMe && (
                                <div className="mt-3 inline-flex items-center gap-2 rounded-full bg-violet-50 px-3 py-1 text-xs font-semibold text-violet-700">
                                  À moi
                                </div>
                              )}
                            </div>
                            <div className={`rounded-2xl border px-3 py-2 text-sm font-semibold ${getStatusColor(req.status)} shadow-sm`}>
                              <div className="flex items-center gap-2">
                                {getStatusIcon(req.status)}
                                <span className="capitalize">{statusLabel(req.status)}</span>
                              </div>
                            </div>
                          </div>
                          <h3 className="mt-6 text-xl font-semibold text-slate-900">{req.workflowType}</h3>
                          <p className="mt-3 text-sm leading-6 text-slate-600">
                            Demande créée le {new Date(req.createdAt).toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                          </p>
                          <div className="mt-6 space-y-3 text-sm text-slate-600">
                            <div className="flex items-center gap-3">
                              <FiUser className="w-4 h-4 text-slate-400" />
                              <span>Créé par {req.creator?.fullName || 'N/A'}</span>
                            </div>
                            {req.assignee?.fullName && (
                              <div className="flex items-center gap-3">
                                <FiUser className="w-4 h-4 text-slate-400" />
                                <span>Assigné à {req.assignee.fullName}</span>
                              </div>
                            )}
                          </div>
                          <div className="mt-8 flex flex-wrap gap-3">
                            <Link
                              to={`/requests/${req.id}`}
                              className="inline-flex items-center justify-center gap-2 rounded-full bg-slate-900 px-4 py-3 text-sm font-semibold text-white transition hover:bg-slate-800"
                            >
                              <FiEye className="w-4 h-4" />
                              Voir
                            </Link>
                            <button
                              type="button"
                            className="inline-flex items-center justify-center gap-2 rounded-full border border-slate-200 bg-slate-200 px-4 py-3 text-sm font-semibold text-slate-700 transition hover:bg-slate-100"
                              onClick={() => handleDelete(req.id)}
                              disabled={deletingId === req.id}
                            >
                              {deletingId === req.id ? (
                                <div className="animate-spin rounded-full h-4 w-4 border-2 border-slate-900 border-t-transparent" />
                              ) : (
                                <FiTrash2 className="w-4 h-4" />
                              )}
                              Supprimer
                            </button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                ) : (
                  <div className="table-container overflow-x-auto">
                    <table className="professional-table min-w-full">
                      <thead>
                        <tr>
                          <th onClick={() => handleSort('reference')} className="cursor-pointer">Référence {sortBy === 'reference' && (sortDir === 'asc' ? <FiChevronUp className="inline-block ml-2" /> : <FiChevronDown className="inline-block ml-2" />)}</th>
                          <th onClick={() => handleSort('workflowType')} className="cursor-pointer">Type de processus {sortBy === 'workflowType' && (sortDir === 'asc' ? <FiChevronUp className="inline-block ml-2" /> : <FiChevronDown className="inline-block ml-2" />)}</th>
                          <th onClick={() => handleSort('createdAt')} className="cursor-pointer">Date de création {sortBy === 'createdAt' && (sortDir === 'asc' ? <FiChevronUp className="inline-block ml-2" /> : <FiChevronDown className="inline-block ml-2" />)}</th>
                          <th onClick={() => handleSort('status')} className="cursor-pointer">Statut {sortBy === 'status' && (sortDir === 'asc' ? <FiChevronUp className="inline-block ml-2" /> : <FiChevronDown className="inline-block ml-2" />)}</th>
                          <th>Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {paginatedRequests.map((req) => (
                          <tr key={req.id}>
                            <td className="font-mono font-semibold text-blue-700">{req.reference}</td>
                            <td className="font-medium text-gray-900">{req.workflowType}</td>
                            <td className="text-gray-600">
                              {new Date(req.createdAt).toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' })}
                            </td>
                            <td className="status-cell">
                              <span className={`status-badge status-badge-${req.status}`}>
                                {statusLabel(req.status)}
                              </span>
                            </td>
                            <td className="action-cell">
                              <Link
                                to={`/requests/${req.id}`}
                                className="action-btn action-btn-primary action-btn-sm"
                                title="Voir"
                              >
                                <FiEye className="w-4 h-4" />
                              </Link>
                              <button
                                type="button"
                                className="action-btn action-btn-danger action-btn-sm"
                                onClick={() => handleDelete(req.id)}
                                disabled={deletingId === req.id}
                                title="Supprimer"
                              >
                                {deletingId === req.id ? (
                                  <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent" />
                                ) : (
                                  <FiTrash2 className="w-4 h-4" />
                                )}
                              </button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                    <div className="mt-4 flex items-center justify-between">
                      <div className="text-sm text-slate-600">Page {currentPage} / {totalPages}</div>
                      <div className="inline-flex items-center gap-2">
                        <button type="button" onClick={() => changePage(-1)} className="inline-flex items-center gap-2 rounded-full border border-slate-200 bg-slate-200 px-3 py-2 text-sm font-semibold text-slate-700" disabled={currentPage === 1}><FiChevronLeft /></button>
                        <button type="button" onClick={() => changePage(1)} className="inline-flex items-center gap-2 rounded-full border border-slate-200 bg-slate-200 px-3 py-2 text-sm font-semibold text-slate-700" disabled={currentPage === totalPages}><FiChevronRight /></button>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default RequestList;
