import React, { useEffect, useState, useMemo } from 'react';
import { getStats, getUsers } from '../services/adminService';
import { getRequests } from '../services/requestService';
import { toast } from 'react-toastify';
import {
  FiUsers, FiFileText, FiClock, FiActivity, FiTrendingUp,
  FiRefreshCw, FiFilter, FiSearch, FiBarChart2, FiPieChart,
  FiUserCheck, FiPercent, FiDownload, FiTarget, FiShield,
  FiChevronLeft, FiChevronRight
} from 'react-icons/fi';
import { Line, Doughnut } from 'react-chartjs-2';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement,
  Title, Tooltip, Legend, ArcElement, Filler
} from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, ArcElement, Filler);

const Statistics = () => {
  const [users, setUsers] = useState([]);
  const [requests, setRequests] = useState([]);
  const [loading, setLoading] = useState(true);
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [filters, setFilters] = useState({ status: '', department: '', dateRange: 'all' });
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 5;

  useEffect(() => {
    loadData();
    if (autoRefresh) {
      const interval = setInterval(loadData, 30000);
      return () => clearInterval(interval);
    }
  }, [autoRefresh]);

  const loadData = async () => {
    try {
      const [statsData, requestsData, usersData] = await Promise.all([getStats(), getRequests(), getUsers()]);
      setRequests(requestsData);
      setUsers(usersData);
    } catch (error) {
      toast.error('Erreur chargement données');
    } finally {
      setLoading(false);
    }
  };

  // Calculs analytiques
  const analytics = useMemo(() => {
    const totalUsers = users.length;
    const activeUsers = users.filter(u => u.isActive).length;
    const totalRequests = requests.length;
    const approved = requests.filter(r => r.status === 'approved').length;
    const rejected = requests.filter(r => r.status === 'rejected').length;
    const pending = requests.filter(r => r.status === 'pending').length;
    const inProgress = requests.filter(r => r.status === 'in_progress').length;
    const returned = requests.filter(r => r.status === 'returned').length;
    const approvalRate = totalRequests ? (approved / totalRequests * 100).toFixed(1) : 0;
    const avgProcessingTime = '2.4j'; // À adapter avec vos données réelles
    const healthScore = (approved / (totalRequests || 1) * 0.6 + activeUsers / (totalUsers || 1) * 0.4) * 100;
    const departments = [...new Set(users.map(u => u.department).filter(Boolean))];
    const monthlyTrend = Array(12).fill(0);
    requests.forEach(r => { if (r.createdAt) monthlyTrend[new Date(r.createdAt).getMonth()] += 1; });
    return { totalUsers, activeUsers, totalRequests, approved, rejected, pending, inProgress, returned, approvalRate, avgProcessingTime, healthScore, departments, monthlyTrend };
  }, [users, requests]);

  // Filtrage
  const filteredRequests = useMemo(() => {
    let filtered = [...requests];
    if (searchTerm) {
      filtered = filtered.filter(r => r.reference?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        r.workflowType?.toLowerCase().includes(searchTerm.toLowerCase()));
    }
    if (filters.status) filtered = filtered.filter(r => r.status === filters.status);
    if (filters.department) filtered = filtered.filter(r => r.user?.department === filters.department);
    if (filters.dateRange !== 'all') {
      const now = new Date();
      const cutoff = new Date();
      if (filters.dateRange === 'month') cutoff.setMonth(now.getMonth() - 1);
      else if (filters.dateRange === 'quarter') cutoff.setMonth(now.getMonth() - 3);
      else if (filters.dateRange === 'year') cutoff.setFullYear(now.getFullYear() - 1);
      filtered = filtered.filter(r => new Date(r.createdAt) >= cutoff);
    }
    return filtered;
  }, [requests, searchTerm, filters]);

  const totalPages = Math.ceil(filteredRequests.length / itemsPerPage);
  const paginatedRequests = filteredRequests.slice((currentPage - 1) * itemsPerPage, currentPage * itemsPerPage);

  // Graphiques
  const lineData = {
    labels: ['Jan', 'Fév', 'Mar', 'Avr', 'Mai', 'Juin', 'Juil', 'Aoû', 'Sep', 'Oct', 'Nov', 'Déc'],
    datasets: [{
      label: 'Demandes',
      data: analytics.monthlyTrend,
      borderColor: '#3b82f6',
      backgroundColor: 'rgba(59,130,246,0.05)',
      fill: true,
      tension: 0.3,
      pointBackgroundColor: '#3b82f6',
      pointBorderColor: '#fff'
    }]
  };

  const statusChartData = {
    labels: ['Approuvées', 'Rejetées', 'En attente', 'En cours', 'Retournées'],
    datasets: [{
      data: [analytics.approved, analytics.rejected, analytics.pending, analytics.inProgress, analytics.returned],
      backgroundColor: ['#10b981', '#ef4444', '#f59e0b', '#3b82f6', '#8b5cf6']
    }]
  };

  const exportCSV = () => {
    const headers = ['Référence', 'Type', 'Statut', 'Date', 'Demandeur'];
    const rows = filteredRequests.map(r => [r.reference, r.workflowType, r.status, r.createdAt, r.user?.name || '']);
    const csv = [headers, ...rows].map(row => row.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `export_stats_${new Date().toISOString()}.csv`;
    a.click();
    URL.revokeObjectURL(url);
    toast.success('Export CSV lancé');
  };

  // Cartes KPI
  const kpis = [
    { label: 'Utilisateurs actifs', value: analytics.activeUsers, change: '+8%', icon: FiUserCheck, color: 'blue' },
    { label: 'Demandes totales', value: analytics.totalRequests, change: '+12%', icon: FiFileText, color: 'indigo' },
    { label: "Taux d'approbation", value: `${analytics.approvalRate}%`, change: '+5%', icon: FiPercent, color: 'green' },
    { label: 'Score de santé', value: `${Math.round(analytics.healthScore)}%`, change: '+2%', icon: FiActivity, color: 'purple' }
  ];

  return (
    <div className="min-h-screen bg-gray-50">
      {/* En-tête style dashboard.avif */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-20">
        <div className="max-w-7xl mx-auto px-6 py-5">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <h1 className="text-2xl font-semibold text-gray-800">Tableau de bord analytique</h1>
              <p className="text-sm text-gray-500 mt-0.5">Indicateurs clés et suivi des demandes</p>
            </div>
            <div className="flex items-center gap-3">
              <button
                onClick={() => setAutoRefresh(!autoRefresh)}
                className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition ${
                  autoRefresh ? 'bg-blue-50 text-blue-700 border border-blue-200' : 'bg-gray-100 text-gray-600 border border-gray-200'
                }`}
              >
                <FiRefreshCw className={`w-4 h-4 ${autoRefresh ? 'animate-spin' : ''}`} />
                {autoRefresh ? 'Live' : 'Auto off'}
              </button>
              <button onClick={loadData} className="p-2 rounded-lg border border-gray-200 text-gray-600 hover:bg-gray-50">
                <FiRefreshCw className="w-4 h-4" />
              </button>
              <button onClick={exportCSV} className="flex items-center gap-2 px-4 py-2 bg-white border border-gray-200 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50">
                <FiDownload className="w-4 h-4" /> Exporter CSV
              </button>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-6 py-8">
        {/* Ligne des KPI (4 cartes) */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          {kpis.map((kpi, idx) => (
            <div key={idx} className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm hover:shadow-md transition">
              <div className="flex items-center justify-between">
                <div className={`p-2 rounded-lg bg-${kpi.color}-50`}>
                  <kpi.icon className={`w-5 h-5 text-${kpi.color}-600`} />
                </div>
                <span className={`text-sm font-medium ${kpi.change.startsWith('+') ? 'text-green-600' : 'text-red-600'} bg-gray-50 px-2 py-0.5 rounded-full`}>
                  {kpi.change}
                </span>
              </div>
              <div className="mt-4">
                <div className="text-3xl font-bold text-gray-800">{kpi.value}</div>
                <div className="text-sm text-gray-500 mt-1">{kpi.label}</div>
              </div>
            </div>
          ))}
        </div>

        {/* Barre de filtres (comme dans le PDF) */}
        <div className="bg-white rounded-xl border border-gray-200 p-4 mb-8 shadow-sm">
          <div className="flex flex-wrap items-center gap-4">
            <FiFilter className="text-gray-400 w-4 h-4" />
            <div className="relative flex-1 min-w-[200px]">
              <FiSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 w-4 h-4" />
              <input
                type="text"
                placeholder="Rechercher par référence ou type..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-3 py-2 border border-gray-200 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <select
              value={filters.status}
              onChange={(e) => setFilters({ ...filters, status: e.target.value })}
              className="border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="">Tous statuts</option>
              <option value="pending">En attente</option>
              <option value="in_progress">En cours</option>
              <option value="approved">Approuvé</option>
              <option value="rejected">Rejeté</option>
              <option value="returned">Retourné</option>
            </select>
            <select
              value={filters.department}
              onChange={(e) => setFilters({ ...filters, department: e.target.value })}
              className="border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="">Tous départements</option>
              {analytics.departments.map(d => <option key={d} value={d}>{d}</option>)}
            </select>
            <select
              value={filters.dateRange}
              onChange={(e) => setFilters({ ...filters, dateRange: e.target.value })}
              className="border border-gray-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="all">Toute période</option>
              <option value="month">Dernier mois</option>
              <option value="quarter">Dernier trimestre</option>
              <option value="year">Dernière année</option>
            </select>
            {(searchTerm || filters.status || filters.department || filters.dateRange !== 'all') && (
              <button onClick={() => { setSearchTerm(''); setFilters({ status: '', department: '', dateRange: 'all' }); }} className="text-sm text-red-500 hover:text-red-700">
                Réinitialiser
              </button>
            )}
          </div>
        </div>

        {/* Graphiques (2 colonnes) */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 mb-8">
          <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="font-semibold text-gray-700">Évolution mensuelle</h2>
              <FiBarChart2 className="text-gray-400" />
            </div>
            <div className="h-72">
              <Line data={lineData} options={{ responsive: true, maintainAspectRatio: false, plugins: { legend: { display: false } }, scales: { y: { grid: { color: '#e5e7eb' } } } }} />
            </div>
          </div>
          <div className="bg-white rounded-xl border border-gray-200 p-5 shadow-sm">
            <div className="flex items-center justify-between mb-4">
              <h2 className="font-semibold text-gray-700">État des demandes</h2>
              <FiPieChart className="text-gray-400" />
            </div>
            <div className="h-72 flex items-center justify-center relative">
              <Doughnut data={statusChartData} options={{ cutout: '60%', plugins: { legend: { position: 'bottom' } } }} />
              <div className="absolute text-center">
                <div className="text-2xl font-bold text-gray-800">{analytics.approvalRate}%</div>
                <div className="text-xs text-gray-500">approuvées</div>
              </div>
            </div>
          </div>
        </div>

        {/* Cartes métriques avancées (temps traitement, conversion, score) */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
          <div className="bg-white rounded-xl border-l-4 border-blue-500 p-5 shadow-sm">
            <div className="flex justify-between items-center">
              <span className="text-gray-500 text-sm">Temps moyen traitement</span>
              <FiClock className="text-blue-500" />
            </div>
            <div className="text-2xl font-bold text-gray-800 mt-2">{analytics.avgProcessingTime}</div>
            <div className="text-xs text-green-600 mt-1">↓ 0.3j vs mois dernier</div>
          </div>
          <div className="bg-white rounded-xl border-l-4 border-green-500 p-5 shadow-sm">
            <div className="flex justify-between items-center">
              <span className="text-gray-500 text-sm">Taux de conversion</span>
              <FiTarget className="text-green-500" />
            </div>
            <div className="text-2xl font-bold text-gray-800 mt-2">{analytics.approvalRate}%</div>
            <div className="text-xs text-gray-500 mt-1">Objectif 75%</div>
          </div>
          <div className="bg-white rounded-xl border-l-4 border-purple-500 p-5 shadow-sm">
            <div className="flex justify-between items-center">
              <span className="text-gray-500 text-sm">Score global</span>
              <FiShield className="text-purple-500" />
            </div>
            <div className="text-2xl font-bold text-gray-800 mt-2">{Math.round(analytics.healthScore)}/100</div>
            <div className="text-xs text-gray-500 mt-1">Excellent</div>
          </div>
        </div>

        {/* Tableau des dernières demandes (similaire au PDF) */}
        <div className="bg-white rounded-xl border border-gray-200 shadow-sm overflow-hidden">
          <div className="px-6 py-4 border-b border-gray-100 flex justify-between items-center">
            <h2 className="font-semibold text-gray-700">Dernières demandes</h2>
            <span className="text-xs text-gray-400">{filteredRequests.length} enregistrements</span>
          </div>
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-100">
              <thead className="bg-gray-50">
                <tr>
                  {['Référence', 'Type', 'Statut', 'Date', 'Demandeur'].map(h => (
                    <th key={h} className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100">
                {paginatedRequests.map(req => (
                  <tr key={req.id} className="hover:bg-gray-50 transition">
                    <td className="px-6 py-4 text-sm font-mono text-gray-700">{req.reference}</td>
                    <td className="px-6 py-4 text-sm text-gray-600">{req.workflowType}</td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex px-2 py-0.5 rounded-full text-xs font-medium
                        ${req.status === 'approved' ? 'bg-green-100 text-green-800' : ''}
                        ${req.status === 'rejected' ? 'bg-red-100 text-red-800' : ''}
                        ${req.status === 'pending' ? 'bg-yellow-100 text-yellow-800' : ''}
                        ${req.status === 'in_progress' ? 'bg-blue-100 text-blue-800' : ''}
                        ${req.status === 'returned' ? 'bg-purple-100 text-purple-800' : ''}
                      `}>
                        {req.status === 'approved' ? 'Approuvée' : req.status === 'rejected' ? 'Rejetée' : req.status === 'pending' ? 'En attente' : req.status === 'in_progress' ? 'En cours' : 'Retournée'}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-500">{new Date(req.createdAt).toLocaleDateString()}</td>
                    <td className="px-6 py-4 text-sm text-gray-600">{req.user?.name || '-'}</td>
                  </tr>
                ))}
                {paginatedRequests.length === 0 && (
                  <tr><td colSpan="5" className="px-6 py-8 text-center text-gray-400">Aucune demande trouvée</td></tr>
                )}
              </tbody>
            </table>
          </div>
          {totalPages > 1 && (
            <div className="px-6 py-3 border-t border-gray-100 flex items-center justify-between">
              <button onClick={() => setCurrentPage(p => Math.max(1, p-1))} disabled={currentPage === 1} className="p-2 rounded-md border border-gray-200 disabled:opacity-40"><FiChevronLeft /></button>
              <span className="text-sm text-gray-600">Page {currentPage} sur {totalPages}</span>
              <button onClick={() => setCurrentPage(p => Math.min(totalPages, p+1))} disabled={currentPage === totalPages} className="p-2 rounded-md border border-gray-200 disabled:opacity-40"><FiChevronRight /></button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default Statistics;