import React, { useState, useEffect, useRef } from 'react';
import { FiSmile, FiSend, FiX, FiCpu } from 'react-icons/fi';
import api from '../services/api';
import { getFallbackReply } from './chatbotUtils';

const ChatBot = () => {
  const [isOpen, setIsOpen] = useState(true);
  const [messages, setMessages] = useState([
    { sender: 'bot', text: 'Bonjour ! Je peux vous aider sur les demandes, workflows, statuts et validations.' },
  ]);
  const [input, setInput] = useState('');
  const [sending, setSending] = useState(false);
  const [error, setError] = useState(null);
  const panelRef = useRef(null);
  const autoStartedRef = useRef(false);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (panelRef.current && !panelRef.current.contains(event.target)) {
        setIsOpen(false);
      }
    };
    if (isOpen) {
      document.addEventListener('mousedown', handleClickOutside);
    }
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [isOpen]);

  const sendMessage = async (text) => {
    const trimmed = text.trim();
    if (!trimmed || sending) return;

    const userMessage = { sender: 'user', text: trimmed };
    const conversation = [...messages, userMessage];

    setMessages((prev) => [...prev, userMessage]);
    setInput('');
    setSending(true);
    setError(null);

    try {
      const payloadMessages = conversation.map((message) => ({
        role: message.sender === 'user' ? 'user' : 'assistant',
        content: message.text,
      }));

      const response = await api.post('/api/chat', {
        messages: payloadMessages,
      });

      const botReply = response.data?.reply || getFallbackReply(trimmed);
      const botMessage = { sender: 'bot', text: botReply };
      setMessages((prev) => [...prev, botMessage]);
    } catch (err) {
      console.error('ChatBot API error:', err);
      const fallbackReply = getFallbackReply(trimmed);
      setError(null);
      setMessages((prev) => [...prev, { sender: 'bot', text: fallbackReply }]);
    } finally {
      setSending(false);
    }
  };

  useEffect(() => {
    if (autoStartedRef.current) return;

    autoStartedRef.current = true;
    setIsOpen(true);
    sendMessage('Bonjour, pouvez-vous m’aider à démarrer ?');
  }, []);

  const handleSend = async (e) => {
    e.preventDefault();
    await sendMessage(input);
  };

  return (
    <div className="relative" ref={panelRef}>
      <button
        onClick={() => setIsOpen((prev) => !prev)}
        className="relative flex h-14 w-14 items-center justify-center rounded-full bg-gradient-to-br from-cyan-600 to-blue-600 text-white shadow-lg shadow-cyan-200 transition-all duration-300 hover:scale-105 hover:shadow-xl"
        title="Chatbot"
      >
        <FiCpu size={22} />
      </button>

      {isOpen && (
        <div className="absolute right-0 mt-3 flex w-[380px] max-h-[560px] flex-col overflow-hidden rounded-[24px] border border-slate-200 bg-white shadow-2xl shadow-slate-300/40 z-50">
          <div className="flex items-center justify-between gap-3 bg-gradient-to-r from-cyan-600 via-sky-600 to-blue-600 p-4 text-white">
            <div className="flex items-center gap-3">
              <div className="flex h-10 w-10 items-center justify-center rounded-full bg-white/20">
                <FiCpu size={18} />
              </div>
              <div>
                <p className="font-semibold">Assistant SOTACIB</p>
                <p className="text-xs text-cyan-100">Disponible pour vous aider</p>
              </div>
            </div>
            <button
              onClick={() => setIsOpen(false)}
              className="rounded-full p-2 transition-colors hover:bg-white/20"
            >
              <FiX size={18} />
            </button>
          </div>

          <div className="flex-1 overflow-y-auto bg-slate-50 p-4">
            <div className="space-y-3">
              {messages.map((message, index) => (
                <div
                  key={`${message.sender}-${index}`}
                  className={`flex ${message.sender === 'bot' ? 'justify-start' : 'justify-end'}`}
                >
                  <div
                    className={`max-w-[90%] rounded-2xl px-4 py-3 text-sm leading-6 shadow-sm ${message.sender === 'bot' ? 'bg-white text-slate-700' : 'bg-cyan-600 text-white'}`}
                  >
                    <p>{message.text}</p>
                  </div>
                </div>
              ))}
              {error && (
                <div className="rounded-xl border border-red-100 bg-red-50 px-3 py-2 text-xs text-red-600">
                  {error}
                </div>
              )}
            </div>
          </div>

          <form onSubmit={handleSend} className="border-t border-slate-200 bg-white p-3">
            <div className="flex items-center gap-2 rounded-2xl border border-slate-200 bg-slate-50 px-2 py-2">
              <input
                type="text"
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Écrire un message..."
                className="flex-1 bg-transparent px-2 py-2 text-sm text-slate-800 outline-none placeholder:text-slate-400"
              />
              <button
                type="submit"
                className="inline-flex h-10 w-10 items-center justify-center rounded-xl bg-cyan-600 text-white transition hover:bg-cyan-700"
              >
                <FiSend size={16} />
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
};

export default ChatBot;
