import React from 'react';
import { useAuth } from '../context/AuthContext';
import NotificationBell from '../Notifications/NotificationBell';
import ChatIcon from '../Chat/ChatIcon';
import ChatBot from '../Chat/ChatBot';
import logo from '../../assets/sotacib-logo.jpg';
import workflowLogo from '../../assets/logo.png';

const Navbar = () => {
  const { user, logout } = useAuth();

  return (
    <nav className="bg-gradient-to-r from-slate-900 via-blue-900 to-cyan-700 px-6 py-4 flex flex-wrap items-center justify-between gap-4 sticky top-0 z-40 shadow-2xl shadow-slate-900/20 backdrop-blur-xl border-b border-white/10">
      <div className="flex items-center gap-4">
        <div className="grid grid-cols-2 gap-3">
          <div className="w-16 h-16 rounded-3xl bg-white/15 border border-white/20 flex items-center justify-center shadow-lg shadow-slate-900/20 overflow-hidden">
            <img src={logo} alt="SOTACIB" className="h-full w-full object-contain" />
          </div>
          <div className="w-16 h-16 rounded-3xl bg-white/15 border border-white/20 flex items-center justify-center shadow-lg shadow-slate-900/20 overflow-hidden">
            <img src={workflowLogo} alt="Workflow" className="h-full w-full object-contain" />
          </div>
        </div>
        <div>
          <h1 className="text-2xl font-semibold tracking-tight text-white">SOTACIB Workflow</h1>
        </div>
      </div>

      <div className="flex flex-wrap items-center gap-3">
        <div className="flex items-center gap-2 rounded-full border border-white/15 bg-white/10 px-3 py-2 text-white shadow-sm shadow-slate-900/10 backdrop-blur">
          <div className="flex items-center gap-2 rounded-full bg-white/10 px-3 py-2 transition hover:bg-white/20">
            <NotificationBell />
            <span className="text-sm font-medium">Alertes</span>
          </div>
          <div className="flex items-center gap-2 rounded-full bg-white/10 px-3 py-2 transition hover:bg-white/20">
            <ChatIcon />
            <span className="text-sm font-medium">Messages</span>
          </div>
          <div className="flex items-center gap-2 rounded-full bg-white/10 px-3 py-2 transition hover:bg-white/20">
            <ChatBot />
            <span className="text-sm font-medium">Assistant</span>
          </div>
        </div>

        <div className="flex items-center gap-3 rounded-full border border-white/15 bg-white/10 px-3 py-2 text-white shadow-sm shadow-slate-900/10 backdrop-blur">
          <div className="grid h-10 w-10 place-items-center rounded-full bg-white/20 text-base font-semibold text-white">
            {user?.fullName?.charAt(0).toUpperCase()}
          </div>
          <div className="text-sm">
            <p className="font-semibold text-white">{user?.fullName}</p>
            <p className="text-[0.75rem] text-slate-200/80">{user?.role}</p>
          </div>
        </div>

        <button
          onClick={logout}
          className="rounded-full border border-red-400/40 bg-red-500/15 px-4 py-2 text-sm font-medium text-white transition hover:bg-red-500/25"
        >
          Déconnexion
        </button>
      </div>
    </nav>
  );
};

export default Navbar;