import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { getRequestById, takeAction, uploadAttachment, generateExcelReport } from '../services/requestService';
import { getWorkflowByName } from '../services/workflowService';
import { useAuth } from '../context/AuthContext';
import { toast } from 'react-toastify';
import './RequestDetailInfo.css';

const RequestDetail = () => {
  const { id } = useParams();
  const { user } = useAuth();
  const navigate = useNavigate();
  const [request, setRequest] = useState(null);
  const [workflow, setWorkflow] = useState(null);
  const [comment, setComment] = useState('');
  const [file, setFile] = useState(null);
  const [stepFormData, setStepFormData] = useState({});
  const [loading, setLoading] = useState(false);

  const normalizeObject = (value) => {
    if (typeof value !== 'string') return value || {};
    try {
      return JSON.parse(value);
    } catch (error) {
      return {};
    }
  };

  const normalizeArray = (value) => {
    if (Array.isArray(value)) return value;
    if (typeof value === 'string') {
      try {
        const parsed = JSON.parse(value);
        return Array.isArray(parsed) ? parsed : [];
      } catch (error) {
        return [];
      }
    }
    return [];
  };

  useEffect(() => {
    loadRequest();
  }, [id]);

  const loadRequest = async () => {
    const data = await getRequestById(id);
    const workflowData = await getWorkflowByName(data.workflowType);
    const normalizedData = normalizeObject(data?.data);
    setRequest({
      ...data,
      data: normalizedData,
      history: normalizeArray(data?.history),
      attachments: normalizeArray(data?.attachments),
    });
    setWorkflow(workflowData);
    setStepFormData(normalizedData || {});
  };

  const handleAction = async (action) => {
    if ((action === 'validate' || action === 'reject') && !comment.trim()) {
      toast.error('Veuillez saisir une note avant de valider ou refuser');
      return;
    }

    const currentStep = workflow?.steps?.[request?.currentStepIndex];
    const requiredFields = Array.isArray(currentStep?.requiredFields) ? currentStep.requiredFields : [];
    const missingFields = requiredFields.filter((fieldName) => {
      const value = stepFormData?.[fieldName];
      return value === null || value === undefined || (typeof value === 'string' && value.trim() === '');
    });
    if (action === 'validate' && missingFields.length > 0) {
      toast.error(`Champs obligatoires: ${missingFields.join(', ')}`);
      return;
    }

    setLoading(true);
    try {
      const result = await takeAction(request.id, action, comment, stepFormData, file);
      if (result.success) {
        toast.success(result.message || 'Action effectuée avec succès');
        if (action === 'validate') {
          navigate('/requests');
        } else {
          loadRequest();
        }
      } else {
        toast.error(result.message || 'Erreur lors de l\'action');
      }
    } catch (error) {
      toast.error('Erreur lors de l\'action');
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadExcel = async () => {
    try {
      setLoading(true);
      
      // Tenter d'abord le service backend (pour quand il sera implémenté)
      try {
        const result = await generateExcelReport(request.id);
        
        if (result.success && result.excelUrl) {
          // Créer un lien pour télécharger le fichier Excel
          const link = document.createElement('a');
          link.href = getExcelDownloadUrl(result.excelUrl);
          link.target = '_blank';
          link.rel = 'noreferrer';
          link.download = `demande_${request.reference}.xlsx`;
          document.body.appendChild(link);
          link.click();
          document.body.removeChild(link);
          
          toast.success('Téléchargement Excel réussi');
          return;
        }
      } catch (backendError) {
        // Si le backend n'est pas encore implémenté (404), utiliser la solution temporaire
        console.log('Backend Excel non disponible, utilisation de la solution temporaire...');
      }
      
      // Solution temporaire : générer un fichier Excel côté client
      await generateExcelClientSide();
      
    } catch (error) {
      toast.error('Erreur lors du téléchargement Excel');
    } finally {
      setLoading(false);
    }
  };

  const generateExcelClientSide = async () => {
    // Créer les données pour l’export CSV
    const excelData = {
      reference: request.reference,
      workflowType: request.workflowType,
      status: request.status,
      creator: request.creator?.fullName || '-',
      assignee: request.assignee?.fullName || request.assignedTo || '-',
      createdAt: new Date(request.createdAt).toLocaleString('fr-FR'),
      data: request.data || {}
    };

    // Convertir en format CSV compatible Excel FR
    const csvContent = convertToCSV(excelData);
    
    // Créer un blob et télécharger
    const blob = new Blob([csvContent], {
      type: 'text/csv;charset=utf-8;'
    });
    
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `demande_${request.reference}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
    
    toast.success('Téléchargement CSV réussi');
  };

  const convertToCSV = (data) => {
    const separator = ';';
    const escapeCsv = (value) => {
      const text = String(value === null || value === undefined ? '' : value);
      const escaped = text.replace(/"/g, '""');
      return `"${escaped}"`;
    };

    const headers = ['Référence', 'Type de demande', 'Statut', 'Créé par', 'Assigné à', 'Date de création'];
    const values = [
      data.reference,
      data.workflowType,
      data.status,
      data.creator,
      data.assignee,
      data.createdAt
    ];

    const dynamicHeaders = [];
    const dynamicValues = [];
    
    Object.entries(data.data).forEach(([key, value]) => {
      const label = getFieldLabel(key);
      dynamicHeaders.push(label);
      if (Array.isArray(value)) {
        dynamicValues.push(escapeCsv(value.join('; ')));
      } else if (typeof value === 'object' && value !== null) {
        dynamicValues.push(escapeCsv(JSON.stringify(value)));
      } else {
        dynamicValues.push(escapeCsv(value || '-'));
      }
    });

    const allHeaders = [...headers, ...dynamicHeaders];
    const allValues = [...values.map(escapeCsv), ...dynamicValues];
    
    const BOM = '\uFEFF';
    return BOM + [allHeaders.join(separator), allValues.join(separator)].join('\n');
  };

  const getExcelDownloadUrl = (url) => {
    // Adapter l'URL de téléchargement Excel (similaire à getPdfDownloadUrl)
    if (url.startsWith('http')) {
      return url;
    }
    return `${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/uploads/excel/${url}`;
  };

  const isAssignedToMe =
    Number(request?.assignedTo) === Number(user?.id) ||
    Number(request?.assignee?.id) === Number(user?.id);
  const currentStep = workflow?.steps?.[request?.currentStepIndex];
  const requiredFields = Array.isArray(currentStep?.requiredFields) ? currentStep.requiredFields : [];

  const fieldLabelMap = {
    recouvrementPlafond: 'Plafond recouvrement',
    compteCollectif: 'Compte collectif',
    groupeTresorerie: 'Groupe trésorerie',
    codeClient: 'Code client',
  };

  const getFieldLabel = (fieldName) => fieldLabelMap[fieldName] || fieldName;
  const getPdfDownloadUrl = (finalPdfUrl) => {
    if (!finalPdfUrl) return null;
    if (String(finalPdfUrl).startsWith('/uploads/')) {
      return `${process.env.REACT_APP_UPLOADS_URL}${finalPdfUrl.replace('/uploads', '')}`;
    }
    const normalized = String(finalPdfUrl).replace(/\\/g, '/');
    const filename = normalized.split('/').pop();
    return `${process.env.REACT_APP_UPLOADS_URL}/pdfs/${filename}`;
  };

  const statusLabel = (status) => {
    switch (status) {
      case 'approved': return 'Approuvée';
      case 'pending': return 'En attente';
      case 'rejected': return 'Rejetée';
      case 'in_progress': return 'En cours';
      case 'draft': return 'Brouillon';
      default: return status;
    }
  };

  const getStatusBadgeClass = (status) => {
    switch (status) {
      case 'approved': return 'bg-gradient-to-r from-emerald-500 to-teal-500 text-white';
      case 'pending': return 'bg-gradient-to-r from-sky-500 to-indigo-500 text-white';
      case 'rejected': return 'bg-gradient-to-r from-rose-500 to-red-600 text-white';
      case 'in_progress': return 'bg-gradient-to-r from-amber-400 to-orange-500 text-slate-950';
      case 'draft': return 'bg-gradient-to-r from-slate-400 to-slate-600 text-white';
      default: return 'bg-slate-200 text-slate-900';
    }
  };

  const formatDate = (value) => {
    if (!value) return '-';
    return new Date(value).toLocaleDateString('fr-FR', { day: '2-digit', month: '2-digit', year: 'numeric' });
  };

  const renderFieldValue = (value) => {
    if (value === null || value === undefined || value === '') {
      return <span className="text-gray-500">-</span>;
    }
    if (Array.isArray(value)) {
      return (
        <div className="space-y-2">
          {value.length === 0 ? (
            <span className="text-gray-500">Aucun élément</span>
          ) : (
            value.map((item, index) => (
              <div key={index} className="rounded-xl border border-slate-200 bg-slate-50 p-3 text-sm text-slate-700">
                {typeof item === 'object' ? JSON.stringify(item, null, 2) : String(item)}
              </div>
            ))
          )}
        </div>
      );
    }
    if (typeof value === 'object') {
      return (
        <div className="space-y-2 text-sm text-slate-700">
          {Object.entries(value).map(([key, nestedValue]) => (
            <div key={key} className="rounded-xl border border-slate-200 bg-slate-50 p-3">
              <p className="text-xs text-slate-500 uppercase tracking-[0.12em]">{key.replace(/([A-Z])/g, ' $1').replace(/^./, (str) => str.toUpperCase())}</p>
              <p>{String(nestedValue)}</p>
            </div>
          ))}
        </div>
      );
    }
    return <span className="text-slate-800 font-medium">{String(value)}</span>;
  };

  const dataEntries = Object.entries(request?.data || {});

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-sky-50 to-indigo-50 py-10">
      <div className="container mx-auto px-4">
        {request && (
          <div className="rounded-[32px] border border-white/80 bg-white/80 shadow-[0_30px_80px_rgba(15,23,42,0.12)] backdrop-blur-xl overflow-hidden">
            <div className="bg-gradient-to-r from-slate-950 via-blue-800 to-indigo-950 px-8 py-10 sm:px-10 sm:py-12">
              <div className="flex flex-col gap-6 lg:flex-row lg:items-start lg:justify-between">
                <div className="max-w-3xl">
                  <span className="inline-flex rounded-full bg-white/10 px-4 py-1 text-xs uppercase tracking-[0.35em] text-slate-200 ring-1 ring-white/20">
                    Détail de la demande
                  </span>
                  <h1 className="mt-4 text-3xl font-semibold tracking-tight text-white sm:text-4xl">
                    Demande {request.reference}
                  </h1>
                  <p className="mt-3 max-w-2xl text-sm leading-7 text-slate-200/85">
                    Visualisez toutes les informations clés, l’historique et les ressources de cette demande.
                  </p>
                </div>
                <div className="flex flex-col gap-4 sm:items-end">
                  <span className={`inline-flex items-center rounded-full px-5 py-2 text-sm font-semibold tracking-wide ${getStatusBadgeClass(request.status)}`}>
                    {statusLabel(request.status)}
                  </span>
                  <button
                    type="button"
                    onClick={() => navigate('/requests')}
                    className="inline-flex items-center justify-center rounded-full border border-white/20 bg-white/10 px-5 py-2 text-sm font-semibold text-white transition hover:bg-white/20"
                  >
                    Retour aux demandes
                  </button>
                </div>
              </div>

              <div className="grid gap-4 mt-10 sm:grid-cols-2 xl:grid-cols-4">
                <div className="rounded-[24px] border border-white/15 bg-white/10 p-5 text-white shadow-lg backdrop-blur">
                  <p className="text-xs uppercase tracking-[0.25em] text-slate-200/80">Type de workflow</p>
                  <p className="mt-3 text-lg font-semibold text-white">{request.workflowType}</p>
                </div>
                <div className="rounded-[24px] border border-white/15 bg-white/10 p-5 text-white shadow-lg backdrop-blur">
                  <p className="text-xs uppercase tracking-[0.25em] text-slate-200/80">Créée le</p>
                  <p className="mt-3 text-lg font-semibold text-white">{formatDate(request.createdAt)}</p>
                </div>
                <div className="rounded-[24px] border border-white/15 bg-white/10 p-5 text-white shadow-lg backdrop-blur">
                  <p className="text-xs uppercase tracking-[0.25em] text-slate-200/80">Créateur</p>
                  <p className="mt-3 text-lg font-semibold text-white">{request.creator?.fullName || '-'}</p>
                </div>
                <div className="rounded-[24px] border border-white/15 bg-white/10 p-5 text-white shadow-lg backdrop-blur">
                  <p className="text-xs uppercase tracking-[0.25em] text-slate-200/80">Assigné à</p>
                  <p className="mt-3 text-lg font-semibold text-white">{request.assignee?.fullName || request.assignedTo || '-'}</p>
                </div>
              </div>
            </div>

            <div className="px-6 py-8 sm:px-10 sm:py-10">
              <div className="request-info-section">
                <h2 className="request-info-title">Informations clés</h2>
                <div className="request-info-grid">
                  <div className="request-info-item">
                    <p className="request-info-label">Référence</p>
                    <p className="request-info-value">{request.reference}</p>
                  </div>
                  <div className="request-info-item">
                    <p className="request-info-label">Statut actuel</p>
                    <p className="request-info-value">{statusLabel(request.status)}</p>
                  </div>
                  <div className="request-info-item">
                    <p className="request-info-label">Étape courante</p>
                    <p className="request-info-value">{workflow?.steps?.[request?.currentStepIndex]?.name || 'N/A'}</p>
                  </div>
                  <div className="request-info-item">
                    <p className="request-info-label">Dernière mise à jour</p>
                    <p className="request-info-value">{formatDate(request.updatedAt || request.createdAt)}</p>
                  </div>
                </div>

                <div className="request-data-section">
                  <h3 className="request-data-title">Données saisies</h3>
                  {dataEntries.length === 0 ? (
                    <div className="request-empty-state">Aucune donnée saisie.</div>
                  ) : (
                    <div className="request-data-grid">
                      {dataEntries.map(([key, value]) => (
                        <div key={key} className="request-data-item">
                          <p className="request-data-label">{getFieldLabel(key)}</p>
                          <div className="request-data-value">{renderFieldValue(value)}</div>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              <div className="card mb-6">
                <h2 className="font-bold mb-4">Historique</h2>
                <div className="space-y-2">
                  {request.history?.map((entry, idx) => (
                    <div key={idx} className="border-l-4 border-blue-300 pl-3 py-1">
                      <p><strong>{entry.action}</strong> par {entry.actorName || entry.actor?.fullName || entry.actor || 'Système'} - {new Date(entry.timestamp).toLocaleString()}</p>
                      <p className="text-sm text-gray-600">{entry.comment}</p>
                    </div>
                  ))}
                </div>
              </div>

              {isAssignedToMe && request.status === 'in_progress' && (
                <div className="rounded-[32px] border border-slate-200 bg-white p-6 shadow-sm mb-6">
                  <h2 className="text-xl font-semibold text-slate-900 mb-4">Action requise</h2>
                  <div className="grid gap-6">
                    <div>
                      <label className="mb-2 block text-sm font-semibold text-slate-700">Commentaire</label>
                      <textarea
                        value={comment}
                        onChange={(e) => setComment(e.target.value)}
                        rows="4"
                        className="w-full rounded-3xl border border-slate-300 bg-slate-50 p-4 text-sm text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-200"
                      />
                    </div>
                    <div>
                      <label className="mb-2 block text-sm font-semibold text-slate-700">Pièce jointe (optionnel)</label>
                      <input
                        type="file"
                        onChange={(e) => setFile(e.target.files[0])}
                        className="w-full rounded-3xl border border-slate-300 bg-white p-3 text-sm text-slate-900"
                      />
                    </div>
                    {requiredFields.length > 0 && (
                      <div className="rounded-3xl border border-slate-200 bg-slate-50 p-5">
                        <p className="font-semibold text-slate-900 mb-3">Champs obligatoires de cette étape</p>
                        <div className="grid gap-4 md:grid-cols-2">
                          {requiredFields.map((fieldName) => (
                            <div key={fieldName}>
                              <label className="mb-2 block text-sm font-medium text-slate-700">{getFieldLabel(fieldName)}</label>
                              <input
                                type="text"
                                value={stepFormData?.[fieldName] || ''}
                                onChange={(e) =>
                                  setStepFormData((prev) => ({
                                    ...prev,
                                    [fieldName]: e.target.value,
                                  }))
                                }
                                placeholder={`Saisir ${getFieldLabel(fieldName).toLowerCase()}`}
                                className="w-full rounded-3xl border border-slate-300 bg-white p-3 text-sm text-slate-900 outline-none transition focus:border-slate-900 focus:ring-2 focus:ring-slate-200"
                              />
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                    <div className="flex flex-wrap gap-3">
                      <button onClick={() => handleAction('validate')} className="inline-flex items-center justify-center rounded-full bg-slate-900 px-6 py-3 text-sm font-semibold text-white transition hover:bg-slate-800" disabled={loading}>Valider</button>
                      <button onClick={() => handleAction('reject')} className="inline-flex items-center justify-center rounded-full bg-gradient-to-r from-rose-500 to-red-600 px-6 py-3 text-sm font-semibold text-white transition hover:from-rose-600 hover:to-red-700" disabled={loading}>Refuser</button>
                      <button onClick={() => handleAction('return')} className="inline-flex items-center justify-center rounded-full border border-slate-300 bg-white px-6 py-3 text-sm font-semibold text-slate-900 transition hover:bg-slate-100" disabled={loading}>Retourner</button>
                    </div>
                  </div>
                </div>
              )}

              {request.finalPdfUrl && (
                <div className="request-pdf-section">
                  <h2 className="request-pdf-title">Récapitulatif et Export</h2>
                  <div className="request-pdf-buttons">
                    <a
                      href={getPdfDownloadUrl(request.finalPdfUrl)}
                      target="_blank"
                      rel="noreferrer"
                      className="request-pdf-btn request-pdf-btn-pdf"
                    >
                      Télécharger le PDF
                    </a>
                    <button
                      onClick={() => handleDownloadExcel()}
                      className="request-pdf-btn request-pdf-btn-excel"
                    >
                      Télécharger CSV
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default RequestDetail;